#!/usr/bin/env python3
"""Generate private b32 asm blocks for ECM stage1 (add + sub, 4096-bit)."""

from pathlib import Path

from mp_asm_block_gen import emit_add_block, emit_sub_block

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "cgbn/backends/opencl/kernels/mp_addsub/stage1/asm_block32_stage1.cl"


def main() -> None:
    parts = [
        "// AUTO-GENERATED by tools/gen_mp_addsub_asm_block32_stage1.py - do not edit.\n",
        "#if defined(ECM_STAGE1_ASM_B32) && defined(__AMDGCN__)\n\n",
        emit_add_block(32, global_addr=False, fix_in_block=False),
        emit_sub_block(32, global_addr=False, fix_in_block=False),
        "#endif\n",
    ]
    OUT.write_text("".join(parts), encoding="utf-8")
    print(f"Wrote {OUT}")


if __name__ == "__main__":
    main()
